"""LSTM model + training loop for the buy/no-buy classifier.BLOCKER: this script assumes `train_labels`, `test_labels` arrays alreadyexist (one binary label per matrix, aligned with train_tensor/test_tensor).buildTrainTestTensor does NOT currently produce these, it only builds inputmatrices. See conversation, this needs to be added before this script canactually run."""import torchimport torch.nn as nnfrom torch.utils.data import TensorDataset, DataLoaderclass BuySignalLSTM(nn.Module):    def __init__(self, num_features, hidden_size=32, num_layers=1, dropout=0.0):        super().__init__()        self.lstm = nn.LSTM(            input_size=num_features,            hidden_size=hidden_size,            num_layers=num_layers,            batch_first=True,  # expects (batch, time_steps, features), matches our tensor shape            dropout=dropout if num_layers > 1 else 0.0,  # dropout between LSTM layers only applies if >1 layer        )        self.output_layer = nn.Linear(hidden_size, 1)    def forward(self, x):        # x shape: (batch, time_steps, num_features)        lstm_out, (hidden, cell) = self.lstm(x)        # hidden shape: (num_layers, batch, hidden_size), take the LAST layer's final hidden state,        # i.e. the summary after processing the entire sequence        last_hidden = hidden[-1]        logit = self.output_layer(last_hidden)  # raw score, NOT yet a probability        return logit.squeeze(-1)  # shape (batch,)def train_model(train_tensor, train_labels, test_tensor, test_labels,                 hidden_size=32, num_layers=1, dropout=0.0,                 learning_rate=0.001, batch_size=32, num_epochs=20,                 weight_decay=0.0, patience=5):    """    train_tensor: numpy array (num_examples, time_steps, num_features), already z-scored    train_labels: numpy array (num_examples,), 0/1    patience: stop training if test_loss hasn't improved for this many    consecutive epochs. The model with the BEST test_loss seen (not the    last epoch's model) is what gets returned.    """    num_features = train_tensor.shape[2]    X_train = torch.tensor(train_tensor, dtype=torch.float32)    y_train = torch.tensor(train_labels, dtype=torch.float32)    X_test = torch.tensor(test_tensor, dtype=torch.float32)    y_test = torch.tensor(test_labels, dtype=torch.float32)    train_dataset = TensorDataset(X_train, y_train)    train_loader = DataLoader(train_dataset, batch_size=batch_size, shuffle=True)    model = BuySignalLSTM(num_features, hidden_size=hidden_size, num_layers=num_layers, dropout=dropout)    # weight_decay adds L2 regularization, penalizing large weights, a    # second lever against overfitting alongside early stopping and dropout    optimizer = torch.optim.Adam(model.parameters(), lr=learning_rate, weight_decay=weight_decay)    loss_fn = nn.BCEWithLogitsLoss()    best_test_loss = float('inf')    best_state = None    best_epoch = 0    epochs_without_improvement = 0    for epoch in range(num_epochs):        model.train()        epoch_loss = 0.0        for X_batch, y_batch in train_loader:            optimizer.zero_grad()            logits = model(X_batch)            loss = loss_fn(logits, y_batch)            loss.backward()            optimizer.step()            epoch_loss += loss.item() * X_batch.size(0)        epoch_loss /= len(train_dataset)        model.eval()        with torch.no_grad():            test_logits = model(X_test)            test_loss = loss_fn(test_logits, y_test).item()            test_probs = torch.sigmoid(test_logits)        print(f"Epoch {epoch+1:3d}/{num_epochs}  train_loss={epoch_loss:.4f}  test_loss={test_loss:.4f}")        if test_loss < best_test_loss:            best_test_loss = test_loss            best_state = {k: v.clone() for k, v in model.state_dict().items()}            best_epoch = epoch + 1            epochs_without_improvement = 0        else:            epochs_without_improvement += 1            if epochs_without_improvement >= patience:                print(f"Early stopping at epoch {epoch+1}, no improvement for {patience} epochs. "                      f"Restoring weights from epoch {best_epoch} (test_loss={best_test_loss:.4f}).")                break    model.load_state_dict(best_state)    model.eval()    with torch.no_grad():        final_probs = torch.sigmoid(model(X_test))    return model, final_probs.numpy()# ---- hyperparameter ranges to sweep once the labeling blocker is resolved ----HYPERPARAM_GRID = {    'hidden_size': [16, 32, 64],    'num_layers': [1, 2],    'dropout': [0.0, 0.2],       # only matters if num_layers > 1    'learning_rate': [0.01, 0.001, 0.0001],    'batch_size': [16, 32, 64],}# num_epochs isn't usually grid-searched directly, better to use a fixed# generous value (e.g. 50-100) plus early stopping once loss stops improving,# worth adding once the basic loop is confirmed working